{
  "tool": "return_delivered_order_items",
  "effect": "MODIFY",
  "action": "Initiates a return process for specified items of a delivered order, triggering a status update to 'return requested' and requiring explicit user confirmation before proceeding.",
  "spans": [
    {
      "source_id": "d14",
      "quote": "return_delivered_order_items — Return some items of a delivered order."
    }
  ],
  "object_type": "delivered order and its associated items (including duplicates) along with their refund/payment adjustment details",
  "object_spans": [
    {
      "source_id": "d14",
      "quote": "The order status will be changed to 'return requested'. The agent needs to explain the return detail and ask for explicit user confirmation (yes/no) to proceed."
    },
    {
      "source_id": "d14",
      "quote": "order_id: string! — The order id, such as '#W0000000'. Be careful there is a '#' symbol at the beginning of the order id."
    },
    {
      "source_id": "d14",
      "quote": "item_ids: array! — The item ids to be returned, each such as '1008292230'. There could be duplicate items in the list."
    },
    {
      "source_id": "d14",
      "quote": "payment_method_id: string! — The payment method id to pay or receive refund for the item price difference, such as 'gift_card_0000000' or 'credit_card_0000000'."
    }
  ],
  "reason": "The tool explicitly modifies the state of the order and its items by enabling a return process, requiring user confirmation, and adjusting payment/refund details."
}
